import { useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  const sa = startOfDay(a);
  return sa.getTime() === startOfDay(b).getTime();
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(startOfDay(new Date()));

  const quickOptions = useMemo(() => {
    const today = startOfDay(new Date());
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    const weekAgo = new Date(today);
    weekAgo.setDate(weekAgo.getDate() - 7);

    return [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: yesterday },
      { label: 'Неделя назад', date: weekAgo },
    ];
  }, []);

  const handleChange = (date: Date | null) => {
    setValue(date);
    onChange?.(date);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-radius-sm)',
        fontFamily: 'var(--jx-font-family)',
      }}
    >
      <div style={{ display: 'flex', gap: '8px' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.label}
            active={isSameDay(value, option.date)}
            onClick={() => handleChange(option.date)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={value} onValueChange={handleChange} />
    </div>
  );
}

